begin;
create or replace function public.create_fleet_metric_definition(p_business_id uuid,p_metric_key text,p_feature_code text,p_name text,p_description text default null,p_unit text default null,p_source_dataset text default null,p_source_metric text default null,p_aggregation text default 'avg',p_direction text default 'higher_is_better',p_scoring_method text default 'threshold',p_goal numeric default null,p_threshold numeric default null,p_max_score numeric default 100,p_scoring_config jsonb default '{}'::jsonb,p_period text default 'week')
returns public.fleet_metric_definitions language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v public.fleet_metric_definitions; f public.feature_catalog; begin if auth.uid() is null then raise exception 'authentication required'; end if; if not public.fleet_metric_controller_authorized(p_business_id) then raise exception 'Fleet controller authorization required'; end if; insert into public.fleet_metric_definitions(business_id,metric_key,feature_code,name,description,unit,source_dataset,source_metric,aggregation,direction,scoring_method,goal,threshold,max_score,scoring_config,period) values(p_business_id,p_metric_key,p_feature_code,p_name,p_description,p_unit,p_source_dataset,p_source_metric,p_aggregation,p_direction,p_scoring_method,p_goal,p_threshold,p_max_score,coalesce(p_scoring_config,'{}'::jsonb),p_period) returning * into v; return v; end $$;
create or replace function public.update_fleet_metric_definition(p_metric_definition_id uuid,p_name text default null,p_description text default null,p_goal numeric default null,p_threshold numeric default null,p_max_score numeric default null,p_scoring_method text default null,p_scoring_config jsonb default null,p_period text default null,p_active boolean default null)
returns public.fleet_metric_definitions language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v public.fleet_metric_definitions; b uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; select business_id into b from public.fleet_metric_definitions where id=p_metric_definition_id; if b is null then raise exception 'Fleet metric definition not found'; end if; if not public.fleet_metric_controller_authorized(b) then raise exception 'Fleet controller authorization required'; end if; update public.fleet_metric_definitions set name=coalesce(p_name,name),description=coalesce(p_description,description),goal=coalesce(p_goal,goal),threshold=coalesce(p_threshold,threshold),max_score=coalesce(p_max_score,max_score),scoring_method=coalesce(p_scoring_method,scoring_method),scoring_config=coalesce(p_scoring_config,scoring_config),period=coalesce(p_period,period),active=coalesce(p_active,active),updated_at=now() where id=p_metric_definition_id returning * into v; return v; end $$;
commit;
